    "C21B": {
      "code": "C21B",
      "level": 0,
      "parent": null,
      "ja": "",
      "en": "",
      "count": 0,
      "ipcCode": "",
      "fTerm": "MANUFACTURE OF IRON OR STEEL (preliminary treatment of ferrous ores or scrap <b>C22B 1/00</b>)<br><br><b><u>Note(s)</u></b><br><br><ul style=\"\"list-style:none\"\"><li>This subclass <u>covers</u>:<ul type=\"\"disc\"\"><li>the production of iron or steel from source materials, e.g. the production of pig-iron;</li><li>apparatus specially adapted therefor, e.g. blast furnaces or air heaters.</li></ul></li></ul><br><br><b><u>Subclass indexes</u></b><br><table width=\"100%\"><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MAKING PIG-IRON</td><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">In blast furnaces</td><td><b>5/00</b>, <b>7/00</b>, <b>9/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">Other processes</td><td><b>11/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:2em;margin:0\"\">General features</td><td><b>3/00</b></td></p></tr></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MAKING IRON</td><td><b>13/00</b>, <b>15/00</b></td></p></tr><tr><td width=\"70%\"><p style=\"\"text-indent:1em;margin:0\"\">MAKING LIQUID STEEL BY DIRECT PROCESSES</td><td><b>13/00</b></td></p></tr></table>",
      "childFlag": 0,
      "sourceFile": "fi_C.txt",
      "kind": "fi"
    },
