      "en": "",
      "count": 0,
      "ipcCode": "",
      "fTerm": "PROCESSING OF PIG-IRON, e.g. REFINING, MANUFACTURE OF WROUGHT-IRON OR STEEL; TREATMENT IN MOLTEN STATE OF FERROUS ALLOYS",
      "childFlag": 0,
      "sourceFile": "fi_C.txt",
      "kind": "fi"
